import {createInk,inkHTML} from './fluid-ink.mjs';
import {seededRandom} from './pattern-geometry.mjs';
import {motionState,motionFrame,motionCSS,motionHTML} from './experiments-core.mjs';
export function motionTool({change}){const $=id=>document.getElementById('motion-'+id),reduce=matchMedia('(prefers-reduced-motion: reduce)');let state=motionState(),phase=.25,playing=false,active=false,frame=0,last=0,lastPaint=0;
 let engine=createInk(),canvas=null,point=null;function seedInk(){engine.clear();const random=seededRandom(state.seed);for(let i=0;i<5;i++)engine.splat(.15+random()*.7,.15+random()*.7,(random()-.5)*.6,(random()-.5)*.6,i%2?state.ink:state.accent,state.radius)}seedInk();
 function paint(){if(state.kind==='ink'){if(!canvas||!$('preview').contains(canvas)){canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;canvas.style.cssText='width:100%;display:block;touch-action:none';canvas.setAttribute('aria-label','Fluid ink: drag to paint, or use Add ink');$('preview').replaceChildren(canvas)}const ctx=canvas.getContext('2d');if(ctx){const small=document.createElement('canvas');small.width=small.height=engine.n;const c=small.getContext('2d');c.putImageData(new ImageData(engine.pixels(state.background),engine.n,engine.n),0,0);ctx.drawImage(small,0,0,960,540)}$('phase-value').textContent='Live simulation';return} $('preview').innerHTML=motionFrame(state,phase);$('phase').value=Math.round(phase*100);$('phase-value').textContent=Math.round(phase*100)+'%'}
 function tick(now){frame=0;if(!active||!playing||reduce.matches||document.hidden)return;if(last){const dt=Math.min(.1,(now-last)/1000);if(state.kind==='ink'){const steps=Math.ceil(dt*state.speed*30);for(let i=0;i<steps;i++)engine.step(dt*state.speed/steps,state)}else phase=(phase+dt*state.speed/8)%1;}last=now;if(now-lastPaint>=1000/30){paint();lastPaint=now}frame=requestAnimationFrame(tick)}
 function sync(){cancelAnimationFrame(frame);frame=0;last=0;if(reduce.matches)playing=false;$('play').disabled=reduce.matches;$('play').textContent=reduce.matches?'Reduced motion enabled':playing?'Pause animation':'Play animation';$('play').setAttribute('aria-pressed',String(playing));if(active&&playing&&!document.hidden)frame=requestAnimationFrame(tick)}
 function inkSVG(){if(canvas?.toDataURL)return `<svg xmlns="http://www.w3.org/2000/svg" width="960" height="540" viewBox="0 0 960 540"><image width="960" height="540" href="${canvas.toDataURL('image/png')}"/></svg>`;return engine.svg(state.background)}
 function draw(){for(const key of Object.keys(state))if($(key))$(key).value=state[key];for(const key of ['speed','amount','amplitude','x1','y1','x2','y2'])$(key+'-value').textContent=key==='speed'?state[key]+'×':String(state[key]);const easing=state.kind==='easing';const ink=state.kind==='ink';$('background-controls').hidden=easing||ink||state.kind==='spring';$('amount').closest?.('label')?.toggleAttribute('hidden',state.kind==='path');$('amplitude').closest?.('label')?.toggleAttribute('hidden',false);$('phase').disabled=ink;for(const [id,kinds] of Object.entries({'seed-controls':['flow','plasma','ink'],'flow-controls':['flow'],'spring-controls':['spring'],'path-controls':['path'],'ink-controls':['ink']}))if($(id))$(id).hidden=!kinds.includes(state.kind);for(const key of ['turbulence','bounce','swirl','dissipation','radius','force'])if($(key+'-value'))$(key+'-value').textContent=state[key];$('easing-controls').hidden=!easing;$('css').hidden=!easing;$('duration').textContent=ink?'Drag to paint · links save seed/settings; HTML saves current ink':state.kind==='spring'?`${(4/state.speed).toFixed(2)} seconds each way · damped spring`:easing?`${(4/state.speed).toFixed(2)} seconds each way · cubic-bezier(${state.x1}, ${state.y1}, ${state.x2}, ${state.y2})`:`${(8/state.speed).toFixed(2)} seconds per loop · movement changes the artwork`;paint();sync();change()}
 for(const key of Object.keys(state))if($(key))$(key).oninput=e=>{state=motionState({...state,[key]:e.target.value});if(['seed','kind'].includes(key))seedInk();if(['x1','y1','x2','y2'].includes(key))$('preset').value='';draw()};
 $('preset').onchange=e=>{const presets={gentle:[.22,0,.36,1],standard:[.4,0,.2,1],linear:[0,0,1,1],snappy:[.76,0,.24,1]},v=presets[e.target.value];if(v){state=motionState({...state,x1:v[0],y1:v[1],x2:v[2],y2:v[3]});draw()}};
 $('play').onclick=()=>{playing=!playing;sync()};$('phase').oninput=e=>{playing=false;phase=Math.min(1,Math.max(0,Number(e.target.value)/100));paint();sync();change()};$('reset').onclick=()=>{state=motionState();seedInk();phase=.25;playing=false;draw()};function at(e){const r=$('preview').getBoundingClientRect();return [(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]}$('preview').onpointerdown=e=>{if(state.kind!=='ink')return;point=at(e);$('preview').setPointerCapture(e.pointerId);engine.splat(...point,0,0,state.ink,state.radius);paint()};$('preview').onpointermove=e=>{if(!point||state.kind!=='ink')return;const p=at(e);engine.splat(...p,(p[0]-point[0])*state.force,(p[1]-point[1])*state.force,state.ink,state.radius);point=p;paint()};$('preview').onpointerup=$('preview').onpointercancel=()=>point=null;if($('splat'))$('splat').onclick=()=>{engine.splat(.5,.5,.2,-.2,state.accent,state.radius);paint()};if($('clear'))$('clear').onclick=()=>{engine.clear();paint()};reduce.addEventListener('change',sync);document.addEventListener('visibilitychange',sync);draw();
 return {get:()=>({...state,phase}),set:s=>{if(s){state=motionState(s);seedInk();phase=Number.isFinite(s.phase)?Math.max(0,Math.min(1,s.phase)):.25;playing=false;draw()}},activate:v=>{active=v;sync()},svg:()=>state.kind==='ink'?inkSVG():motionFrame(state,phase),html:()=>state.kind==='ink'?inkHTML(state,engine.snapshot()):motionHTML({...state,phase}),css:()=>motionCSS(state)}
}
